package com.cenedu.backend.ai.problem.render; import com.cenedu.backend.domain.problem.authoring.diagram.*; public final class SolidGeometrySvgRenderer { public String render(SolidGeometryDiagramSpecV1 s){int p=s.viewport().padding(),w=s.viewport().width(),h=s.viewport().height(),dx=40,dy=23;return "<polygon points=\""+p+","+(h-p)+" "+(w-p)+","+(h-p)+" "+(w-p-dx)+","+(p+dy)+" "+(p+dx)+","+p+"\" fill=\"none\" stroke=\"#000000\"/>"+"<line x1=\""+p+"\" y1=\""+(h-p)+"\" x2=\""+(p+dx)+"\" y2=\""+p+"\" stroke=\"#000000\" stroke-dasharray=\"4 3\"/>";} }
